CREATE TABLE "Auditoria" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Fecha" timestamp with time zone NOT NULL,
    "UsuarioId" text NOT NULL,
    "EscuelaId" text NOT NULL,
    "Accion" text NOT NULL,
    "RecursoId" text NOT NULL,
    "Version" integer NOT NULL,
    CONSTRAINT "PK_Auditoria" PRIMARY KEY ("Id")
);


CREATE TABLE "Periodos" (
    "Id" text NOT NULL,
    "EscuelaId" text NOT NULL,
    "SemestreId" text NOT NULL,
    "Momento" text NOT NULL,
    "Activo" boolean NOT NULL,
    "Version" integer NOT NULL,
    CONSTRAINT "PK_Periodos" PRIMARY KEY ("Id")
);


CREATE TABLE "Personas" (
    "Id" text NOT NULL,
    "Tipo" text NOT NULL,
    "EscuelaId" text NOT NULL,
    "Ciclo" integer,
    "Activa" boolean NOT NULL,
    "DatosJson" jsonb NOT NULL,
    CONSTRAINT "PK_Personas" PRIMARY KEY ("Id")
);


CREATE TABLE "Asignaciones" (
    "Id" text NOT NULL,
    "EstudianteId" text NOT NULL,
    "TutorId" text NOT NULL,
    "EscuelaId" text NOT NULL,
    "SemestreId" text NOT NULL,
    "Grupo" text,
    "DatosJson" jsonb NOT NULL,
    "Activa" boolean NOT NULL,
    "Version" integer NOT NULL,
    CONSTRAINT "PK_Asignaciones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Asignaciones_Personas_EstudianteId" FOREIGN KEY ("EstudianteId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Asignaciones_Personas_TutorId" FOREIGN KEY ("TutorId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Expediente" (
    "EstudianteId" text NOT NULL,
    "Periodo" text NOT NULL,
    "Campo" text NOT NULL,
    "Valor" text NOT NULL,
    "DocumentoId" text NOT NULL,
    "Actualizado" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Expediente" PRIMARY KEY ("EstudianteId", "Periodo", "Campo"),
    CONSTRAINT "FK_Expediente_Personas_EstudianteId" FOREIGN KEY ("EstudianteId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Horarios" (
    "Id" text NOT NULL,
    "EstudianteId" text NOT NULL,
    "SemestreId" text NOT NULL,
    "Dia" integer NOT NULL,
    "HoraInicio" text NOT NULL,
    "HoraFin" text NOT NULL,
    "DatosJson" jsonb NOT NULL,
    CONSTRAINT "PK_Horarios" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Horarios_Personas_EstudianteId" FOREIGN KEY ("EstudianteId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Matriculas" (
    "Id" text NOT NULL,
    "EstudianteId" text NOT NULL,
    "SemestreId" text NOT NULL,
    "DatosJson" jsonb NOT NULL,
    CONSTRAINT "PK_Matriculas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Matriculas_Personas_EstudianteId" FOREIGN KEY ("EstudianteId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Sesiones" (
    "Id" text NOT NULL,
    "TutorId" text NOT NULL,
    "EscuelaId" text NOT NULL,
    "SemestreId" text NOT NULL,
    "Tipo" text NOT NULL,
    "Fecha" text NOT NULL,
    "HoraInicio" text NOT NULL,
    "HoraFin" text NOT NULL,
    "FinUtc" timestamp with time zone NOT NULL,
    "Modalidad" text NOT NULL,
    "Lugar" text NOT NULL,
    "Tema" text NOT NULL,
    "Objetivo" text NOT NULL,
    "Estado" text NOT NULL,
    "AsistenciaConfirmada" boolean NOT NULL,
    "AcuerdosJson" jsonb NOT NULL,
    "InstrumentoId" text,
    "Version" integer NOT NULL,
    CONSTRAINT "PK_Sesiones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Sesiones_Personas_TutorId" FOREIGN KEY ("TutorId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Usuarios" (
    "Id" text NOT NULL,
    "Issuer" text NOT NULL,
    "Subject" text NOT NULL,
    "Rol" text NOT NULL,
    "PersonaId" text NOT NULL,
    "EscuelaId" text NOT NULL,
    "Identificador" text NOT NULL,
    "PasswordHashDesarrollo" text,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Usuarios_Personas_PersonaId" FOREIGN KEY ("PersonaId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Asistencias" (
    "SesionId" text NOT NULL,
    "EstudianteId" text NOT NULL,
    "Estado" text NOT NULL,
    "HoraRegistro" text,
    "Observacion" text,
    CONSTRAINT "PK_Asistencias" PRIMARY KEY ("SesionId", "EstudianteId"),
    CONSTRAINT "FK_Asistencias_Personas_EstudianteId" FOREIGN KEY ("EstudianteId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Asistencias_Sesiones_SesionId" FOREIGN KEY ("SesionId") REFERENCES "Sesiones" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Instrumentos" (
    "Id" text NOT NULL,
    "Formato" text NOT NULL,
    "EscuelaId" text NOT NULL,
    "SemestreId" text NOT NULL,
    "TutorId" text NOT NULL,
    "EstudianteId" text,
    "SesionId" text,
    "Estado" text NOT NULL,
    "Avance" integer NOT NULL,
    "Version" integer NOT NULL,
    "Creado" timestamp with time zone NOT NULL,
    "Actualizado" timestamp with time zone NOT NULL,
    "Enviado" timestamp with time zone,
    "RevisadoPor" text,
    "RespuestasJson" jsonb NOT NULL,
    "ObservacionesJson" jsonb NOT NULL,
    CONSTRAINT "PK_Instrumentos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Instrumentos_Personas_EstudianteId" FOREIGN KEY ("EstudianteId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Instrumentos_Personas_TutorId" FOREIGN KEY ("TutorId") REFERENCES "Personas" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Instrumentos_Sesiones_SesionId" FOREIGN KEY ("SesionId") REFERENCES "Sesiones" ("Id") ON DELETE RESTRICT
);


CREATE UNIQUE INDEX "IX_Asignaciones_EstudianteId_SemestreId" ON "Asignaciones" ("EstudianteId", "SemestreId") WHERE "Activa" = TRUE;


CREATE INDEX "IX_Asignaciones_TutorId" ON "Asignaciones" ("TutorId");


CREATE INDEX "IX_Asistencias_EstudianteId" ON "Asistencias" ("EstudianteId");


CREATE INDEX "IX_Horarios_EstudianteId" ON "Horarios" ("EstudianteId");


CREATE INDEX "IX_Instrumentos_EstudianteId" ON "Instrumentos" ("EstudianteId");


CREATE UNIQUE INDEX "IX_Instrumentos_SesionId_EstudianteId_Formato" ON "Instrumentos" ("SesionId", "EstudianteId", "Formato") WHERE "SesionId" IS NOT NULL;


CREATE INDEX "IX_Instrumentos_TutorId" ON "Instrumentos" ("TutorId");


CREATE INDEX "IX_Matriculas_EstudianteId" ON "Matriculas" ("EstudianteId");


CREATE UNIQUE INDEX "IX_Periodos_EscuelaId" ON "Periodos" ("EscuelaId") WHERE "Activo" = TRUE;


CREATE UNIQUE INDEX "IX_Periodos_EscuelaId_SemestreId" ON "Periodos" ("EscuelaId", "SemestreId");


CREATE INDEX "IX_Sesiones_TutorId_Fecha" ON "Sesiones" ("TutorId", "Fecha");


CREATE UNIQUE INDEX "IX_Usuarios_Issuer_Subject" ON "Usuarios" ("Issuer", "Subject");


CREATE INDEX "IX_Usuarios_PersonaId" ON "Usuarios" ("PersonaId");


